        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        SColors[ 0] := '      wbgbo            ';
        SColors[ 1] := '      wygyo            ';
        SColors[ 2] := '      wgwwy            ';
        SColors[ 3] := '      rgogw            ';
        SColors[ 4] := '      wwbby            ';
        SColors[ 5] := 'rroyr bowyb rgrby gywwg';
