        SColors[ 8] := 'ybgwo wgoyb roywo brbrg';
        SColors[ 9] := 'yrrgw grbwb oryww ooobr';
        SColors[10] := '      ogrgy            ';
        SColors[11] := '      ybryy            ';
        SColors[12] := '      gyywg            ';
        SColors[13] := '      wowbb            ';
        SColors[14] := '      grgyb            ';

        W := 0.5;

        N := 5;
        WD := W * 0.28;
        D[0] := WD * (-N/2 + 1);
        for i := 1 to N - 2 do
            D[i] := D[i-1] + WD;

        DX :=-0.01;
        DY :=-0.10;
        DZ := 0.07;

        SColor := 'robgyw';
        function GetColor(X, Y);
        begin
            Result := -1;
            C := copy(SColors[N * SY + Y], ((N + 1) * SX + 1) + X, 1);
            i := Pos(C, SColor);
            if i > 0 then
                Result := Colors[i - 1];
        end;

